      { id: 2, question: 'Which of these is a valid numeric separator usage?', options: ['_100', '100_', '1_00_000', '0x_FF_FF'], correctIndex: 2, explanation: '1_00_000 is valid. Underscores cannot be at the start (_100), end (100_), or immediately after certain prefixes.' },
      { id: 3, question: 'What is the purpose of numeric separators?', options: ['To make numbers bigger', 'To improve readability of large numbers', 'To create string concatenation', 'To parse numbers faster'], correctIndex: 1, explanation: 'Numeric separators make large numbers easier to read by grouping digits visually.' }
